rect_rows=range(2,9)
rect_cols=range(9,16)
markers={(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)}
# Conditional rule: each marker outside the rectangle but aligned with its row or column
# extends that rectangle line toward the marker-side grid edge.
ray_cells=set()
for r,c in markers:
    if r in rect_rows and c < 9:
        ray_cells.update((r,x) for x in range(0,9))
    elif r in rect_rows and c > 15:
        ray_cells.update((r,x) for x in range(16,20))
    elif c in rect_cols and r > 8:
        ray_cells.update((x,c) for x in range(9,20))
    elif c in rect_cols and r < 2:
        ray_cells.update((x,c) for x in range(0,2))
print('horizontal rows:', [(r, 'left' if any((r,c) in ray_cells for c in range(9)) else '', 'right' if any((r,c) in ray_cells for c in range(16,20)) else '') for r in [2,3,4,7,8]])
print('vertical columns:', [(c, min(r for r,cc in ray_cells if cc==c), max(r for r,cc in ray_cells if cc==c)) for c in [9,13,15]])
